def BoundedlyComplete (P : ℕ → E →L[K] E) : Prop :=
  ∀ x : ℕ → E, (∀ m n, m ≤ n → P m (x n) = x m) →
    (∃ M : ℝ, ∀ n, ‖x n‖ ≤ M) → ∃ a, Tendsto x atTop (𝓝 a)

